<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('contacts.view');
$pageTitle=t('contacts');$pdo=db();
$q=trim((string)($_GET['q']??''));$country=trim((string)($_GET['country']??''));$status=(string)($_GET['status']??'');$owner=(int)($_GET['owner']??0);
$where=['1=1'];$params=[];
if($q!==''){$where[]='(ct.first_name LIKE ? OR ct.last_name LIKE ? OR ct.email LIKE ? OR c.company_name LIKE ?)';$term='%'.$q.'%';array_push($params,$term,$term,$term,$term);}
if($country!==''){$where[]='c.country=?';$params[]=$country;}if(in_array($status,['active','inactive','lead'],true)){$where[]='ct.status=?';$params[]=$status;}if($owner>0){$where[]='ct.owner_user_id=?';$params[]=$owner;}
$sql="SELECT ct.*,c.company_name,c.country,u.name owner_name,(SELECT COUNT(*) FROM activities a WHERE a.contact_id=ct.id) activity_count,(SELECT MAX(created_at) FROM activities a WHERE a.contact_id=ct.id) last_activity FROM contacts ct LEFT JOIN clients c ON c.id=ct.client_id LEFT JOIN users u ON u.id=ct.owner_user_id WHERE ".implode(' AND ',$where)." ORDER BY COALESCE(c.country,''),ct.first_name,ct.last_name";
$stmt=$pdo->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();
$countries=$pdo->query("SELECT DISTINCT country FROM clients WHERE country IS NOT NULL AND country<>'' ORDER BY country")->fetchAll(PDO::FETCH_COLUMN);$users=$pdo->query("SELECT id,name FROM users WHERE is_active=1 ORDER BY name")->fetchAll();
require __DIR__.'/includes/header.php';
?>
<section class="panel"><div class="panel-header"><div><h2>Base de datos de personas</h2><span class="table-sub">Fichas individuales, correos, teléfonos, historial de actividad, notas y empresa relacionada.</span></div><?php if(has_permission('contacts.manage')):?><div class="actions"><a class="btn btn-light btn-small" href="data_tools.php?type=contacts">Importar / exportar</a><a class="btn btn-primary btn-small" href="contact_form.php">+ CREAR CONTACTO</a></div><?php endif;?></div>
<div class="panel-body"><form class="filters-wide" method="get"><label>Buscar<input name="q" value="<?=e($q)?>" placeholder="Nombre, email o empresa"></label><label>País<select name="country"><option value="">Todos</option><?php foreach($countries as$item):?><option <?=$country===$item?'selected':''?>><?=e($item)?></option><?php endforeach;?></select></label><label>Estado<select name="status"><option value="">Todos</option><option value="active" <?=$status==='active'?'selected':''?>>Activo</option><option value="lead" <?=$status==='lead'?'selected':''?>>Lead</option><option value="inactive" <?=$status==='inactive'?'selected':''?>>Inactivo</option></select></label><label>Responsable<select name="owner"><option value="0">Todos</option><?php foreach($users as$u):?><option value="<?=$u['id']?>" <?=$owner===(int)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><button class="btn btn-secondary">FILTRAR</button></form></div>
<div class="table-wrap"><?php if(!$rows):?><div class="empty">No hay contactos con esos filtros.</div><?php else:?><table class="data-table"><thead><tr><th>Contacto</th><th>Empresa / país</th><th>Comunicación</th><th>Responsable</th><th>Actividad</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as$row):?><tr><td><a class="table-title" href="contact_view.php?id=<?=$row['id']?>"><?=e(trim($row['first_name'].' '.$row['last_name']))?></a><span class="table-sub"><?=e($row['job_title']?:$row['department']?:'Sin cargo')?></span></td><td><?=e($row['company_name']?:'Contacto independiente')?><span class="table-sub"><?=e($row['country']?:'Sin país')?></span></td><td><?php if($row['email']):?><a href="mailto:<?=e($row['email'])?>"><?=e($row['email'])?></a><?php endif;?><span class="table-sub"><?=e($row['whatsapp']?:$row['phone']?:'—')?></span></td><td><?=e($row['owner_name']?:'Sin asignar')?></td><td><strong><?=(int)$row['activity_count']?></strong><span class="table-sub"><?=$row['last_activity']?e((new DateTimeImmutable($row['last_activity']))->format('d/m/Y H:i')):'Sin actividad'?></span></td><td><span class="badge badge-<?=$row['status']==='active'?'green':($row['status']==='lead'?'orange':'gray')?>"><?=e(ucfirst($row['status']))?></span></td><td><div class="actions"><a class="btn btn-light btn-small" href="contact_view.php?id=<?=$row['id']?>">Ver</a><?php if(has_permission('contacts.manage')):?><a class="btn btn-light btn-small" href="contact_form.php?id=<?=$row['id']?>">Editar</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section>
<?php require __DIR__.'/includes/footer.php';?>
